import React from 'react';

function StarRating({ rating }) {
  return (
    <div className="stars">
      {[1, 2, 3, 4, 5].map(star => {
  if (star <= Math.floor(rating)) {
    return <span key={star} className="star filled">★</span>;
  } else if (star === Math.ceil(rating) && rating % 1 !== 0) {
    return <span key={star} className="star half">★</span>; // half star
  } else {
    return <span key={star} className="star">★</span>;
  }
})}
      <span className="rating-value">({rating})</span>
    </div>
  );
}

export default function ProductCard({ product, onAddToCart, inCart }) {
  return (
    <div className="product-card">
      <div className="product-image-wrap">
        <img src={product.image} alt={product.name} className="product-image" loading="lazy" />
        <span className="product-category">{product.category}</span>
      </div>
      <div className="product-body">
        <h3 className="product-name">{product.name}</h3>
        <p className="product-desc">{product.description}</p>
        <StarRating rating={product.rating} />
        <div className="product-footer">
          <span className="product-price">₹{product.price.toLocaleString('en-IN')}</span>
          <button
            className={`add-btn ${inCart ? 'in-cart' : ''}`}
            onClick={() => onAddToCart(product)}
          >
            {inCart ? '✓ Added' : '+ Add to Cart'}
          </button>
        </div>
      </div>
    </div>
  );
}
